using System.Globalization;
using System.Windows.Markup;

namespace NaraNote.App.Localization;

public static class UiText
{
    private static readonly string SystemLanguage = SelectLanguage(CultureInfo.CurrentUICulture.TwoLetterISOLanguageName);
    public static string Language { get; private set; } = SystemLanguage;

    public static void SetLanguage(string? preference)
    {
        Language = string.Equals(preference, "system", StringComparison.OrdinalIgnoreCase)
            ? SystemLanguage
            : SelectLanguage(preference ?? "en");
        var cultureName = Language switch { "fr" => "fr-FR", "es" => "es-ES", "vi" => "vi-VN", "ko" => "ko-KR", _ => "en-US" };
        CultureInfo.CurrentUICulture = CultureInfo.GetCultureInfo(cultureName);
        CultureInfo.DefaultThreadCurrentUICulture = CultureInfo.CurrentUICulture;
    }

    public static string Get(string key) =>
        Catalog.TryGetValue(Language, out var language) && language.TryGetValue(key, out var value)
            ? value
            : English.TryGetValue(key, out var fallback) ? fallback : key;

    public static string Format(string key, params object[] args) => string.Format(CultureInfo.CurrentCulture, Get(key), args);

    private static string SelectLanguage(string language) => language is "en" or "fr" or "es" or "vi" or "ko" ? language : "en";

