    private static void Add(string language, params (string Key, string Value)[] values)
    {
        foreach (var (key, value) in values) Catalog[language][key] = value;
    }

    private static Dictionary<string, string> Override(params (string Key, string Value)[] values) => values.ToDictionary(item => item.Key, item => item.Value);
}

[MarkupExtensionReturnType(typeof(string))]
public sealed class LocExtension(string key) : MarkupExtension
{
    public string Key { get; } = key;
    public override object ProvideValue(IServiceProvider serviceProvider) => UiText.Get(Key);
}
